package in.malabartrails; import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="destinations") public class Destination { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Column(nullable=false,unique=true) public String slug;@Column(nullable=false) public String name;@Column(length=800) public String summary;@Column(columnDefinition="text") public String description;@Column(name="cover_image_url",columnDefinition="text") public String coverImageUrl;public Double latitude;public Double longitude;@Column(name="map_embed_url",columnDefinition="text") public String mapEmbedUrl;@Column(name="seo_title") public String seoTitle;@Column(name="seo_description") public String seoDescription;@Column(nullable=false) public String status; }
